// The Lucide icon subset as a font, shared by every window that draws icons: one copy of the TTF bytes
// (host/data/icons_lucide.inc, generated by tools/gen_lucide_icons.py) and one rule for placing it on a text line.
#pragma once

#include <vector>

struct ImFont;
struct ImFontAtlas;
struct ImFontConfig;

namespace PobIcon {

// The primary face's ascent as a fraction of its line height, read from 'hhea'
// the way stb_truetype scales it (ascent / (ascent - descent)). 0.8 when the
// table cannot be read.
float HheaAscentRatio(const std::vector<unsigned char>& ttf);

// Merges the icon font into the face that was added last, at `px`.
// `mergeCfg` is the caller's merge-mode config (FontDataOwnedByAtlas = false, MergeMode = true). Lucide's em box is
// all ascent (glyphs fill ~4%..96%), so icons are shifted to centre their box on the text line. Call it LAST for a
// face, so a text font using the same Private Use Area keeps its glyphs.
void MergeInto(ImFontAtlas* atlas, float px, const ImFontConfig& mergeCfg, float primaryAscent);

// True when `face` can draw the icons (asked of the built atlas, never assumed).
bool FaceHasIcons(const ImFont* face);

} // namespace PobIcon
